class Solution:
    def hammingWeight(self, n: int) -> int:
        c = 0
        while n:
            n &= (n - 1)
            c += 1
        return c

reference_solution.javascript:
function hammingWeight(n) {
    let c = 0;
    while (n !== 0) {
        n = n & (n - 1);
        c++;
    }
    return c;
}
